DROP TABLE IF EXISTS `certificados_generados`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `certificados_generados` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `colaborador_id` int NOT NULL,
  `capacitacion_id` int NOT NULL,
  `archivo_pdf` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `fecha_generacion` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `fecha_actualizacion` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `certificado_unico` (`colaborador_id`,`capacitacion_id`),
  KEY `idx_colab_cap` (`colaborador_id`,`capacitacion_id`) USING BTREE,
  KEY `idx_fecha_gen` (`fecha_generacion`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
