DROP TABLE IF EXISTS `colaboradores`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `colaboradores` (
  `idColaborador` int NOT NULL AUTO_INCREMENT,
  `ccColaborador` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `nombreColaborador` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `apellidoColaborador` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `cargoColaborador` int NOT NULL,
  `correoColaborador` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `telefoColaborador` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `estadoColaborador` int NOT NULL,
  `nivelcolaborador` int NOT NULL,
  `regionalcolab` int NOT NULL,
  `id_centroop` int DEFAULT NULL,
  PRIMARY KEY (`idColaborador`),
  KEY `fkcargo` (`cargoColaborador`),
  KEY `fk_nivel` (`nivelcolaborador`),
  KEY `fk_regionalcolab` (`regionalcolab`),
  KEY `fk_centroop_colaborador` (`id_centroop`),
  CONSTRAINT `fk_centroop_colaborador` FOREIGN KEY (`id_centroop`) REFERENCES `centroop` (`idCentrOp`),
  CONSTRAINT `fk_nivel` FOREIGN KEY (`nivelcolaborador`) REFERENCES `niveles` (`idnivel`),
  CONSTRAINT `fk_regionalcolab` FOREIGN KEY (`regionalcolab`) REFERENCES `regional` (`idregional`),
  CONSTRAINT `fkcargo` FOREIGN KEY (`cargoColaborador`) REFERENCES `cargo` (`idCargo`)
) ENGINE=InnoDB AUTO_INCREMENT=1679 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

