--
-- Table structure for table `examenes_registroexamenes`
--

DROP TABLE IF EXISTS `examenes_registroexamenes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `examenes_registroexamenes` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `nombre_trabajador` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `documento_trabajador` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `fecha_registro` datetime(6) NOT NULL,
  `cargo_id` int NOT NULL,
  `correo_lote_id` bigint NOT NULL,
  `empresa_id` int NOT NULL,
  `id_centro` int DEFAULT NULL,
  `uuid_trabajador` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `estado_trabajador` int NOT NULL,
  `examenes_asignados` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `tipo_examen` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `ciudad` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `examenes_registroexamenes_cargo_id_8ceb1bc4_fk_cargo_idCargo` (`cargo_id`),
  KEY `examenes_registroexa_empresa_id_520be227_fk_epresa_Id` (`empresa_id`),
  KEY `examenes_registroexamenes_documento_trabajador_8ef4634e` (`documento_trabajador`),
  KEY `examenes_registroexa_id_centro_e80ecc24_fk_centroop_` (`id_centro`),
  KEY `examenes_registroexamenes_uuid_trabajador_idx` (`uuid_trabajador`),
  KEY `examenes_registroexamenes_correo_lote_id_9f3937ad` (`correo_lote_id`),
  CONSTRAINT `examenes_registroexa_correo_lote_id_9f3937ad_fk_examenes_` FOREIGN KEY (`correo_lote_id`) REFERENCES `examenes_correoexamenenviado` (`id`),
  CONSTRAINT `examenes_registroexa_empresa_id_520be227_fk_epresa_Id` FOREIGN KEY (`empresa_id`) REFERENCES `epresa` (`Idempresa`),
  CONSTRAINT `examenes_registroexa_id_centro_e80ecc24_fk_centroop_` FOREIGN KEY (`id_centro`) REFERENCES `centroop` (`idCentrOp`),
  CONSTRAINT `examenes_registroexamenes_cargo_id_8ceb1bc4_fk_cargo_idCargo` FOREIGN KEY (`cargo_id`) REFERENCES `cargo` (`idCargo`)
) ENGINE=InnoDB AUTO_INCREMENT=656 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

