CREATE TABLE `respuestas_colaboradores` (
  `id` int NOT NULL AUTO_INCREMENT,
  `idColaborador` int NOT NULL,
  `idPregunta` int NOT NULL,
  `idRespuesta` int NOT NULL,
  PRIMARY KEY (`id`),
